// Array para armazenar as tarefas
let tarefas = [];

// Gerador de códigos
let codigoAtual = 0;


// 1. Validar os dados
function validarDadosDaTarefa(titulo, prioridade) {

    if (titulo.trim().length < 5) {
            throw new Error("O título precisa ter no mínimo 5 caracteres!");
                }

                    if (prioridade < 1 || prioridade > 3) {
                            throw new Error("A prioridade deve estar entre 1 e 3!");
                                }

                                }


                                // 2. Cadastrar tarefa
                                function cadastrarTarefa(titulo, prioridade) {

                                    validarDadosDaTarefa(titulo, prioridade);

                                        codigoAtual++;

                                            const tarefa = {
                                                    codigo: codigoAtual,
                                                            titulo: titulo.trim(),
                                                                    prioridade: Number(prioridade),
                                                                            status: true
                                                                                };

                                                                                    tarefas.push(tarefa);

                                                                                        listarTarefas();

                                                                                        }


                                                                                        // 3. Listar tarefas
                                                                                        function listarTarefas() {

                                                                                            const lista = document.getElementById("tarefas");

                                                                                                lista.innerHTML = "";

                                                                                                    if (tarefas.length === 0) {
                                                                                                            lista.innerHTML = "<p>Nenhuma tarefa cadastrada.</p>";
                                                                                                                    return;
                                                                                                                        }

                                                                                                                            tarefas.forEach(tarefa => {

                                                                                                                                    let prioridadeTexto = "";
                                                                                                                                            let classe = "";

                                                                                                                                                    if (tarefa.prioridade === 1) {
                                                                                                                                                                prioridadeTexto = "Alta";
                                                                                                                                                                            classe = "alta";
                                                                                                                                                                                    } else if (tarefa.prioridade === 2) {
                                                                                                                                                                                                prioridadeTexto = "Média";
                                                                                                                                                                                                            classe = "media";
                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                prioridadeTexto = "Baixa";
                                                                                                                                                                                                                                            classe = "baixa";
                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                            const statusTexto = tarefa.status
                                                                                                                                                                                                                                                                        ? "Em andamento"
                                                                                                                                                                                                                                                                                    : "Concluída";

                                                                                                                                                                                                                                                                                            const div = document.createElement("div");

                                                                                                                                                                                                                                                                                                    div.className = tarefa.status
                                                                                                                                                                                                                                                                                                                ? "tarefa"
                                                                                                                                                                                                                                                                                                                            : "tarefa concluida";

                                                                                                                                                                                                                                                                                                                                    div.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                <h3>${tarefa.titulo}</h3>

                                                                                                                                                                                                                                                                                                                                                            <p>Código: ${tarefa.codigo}</p>

                                                                                                                                                                                                                                                                                                                                                                        <p>Prioridade:
                                                                                                                                                                                                                                                                                                                                                                                        <span class="${classe}">
                                                                                                                                                                                                                                                                                                                                                                                                            ${prioridadeTexto}
                                                                                                                                                                                                                                                                                                                                                                                                                            </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>Status: ${statusTexto}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? `<button onclick="concluirTarefa(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Concluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       </button>`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       : ""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               <button onclick="alterarPrioridade(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               Alterar Prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           lista.appendChild(div);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // 4. Buscar tarefa pelo código
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               function buscarTarefa(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const tarefa = tarefas.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           tarefa => tarefa.codigo === Number(codigo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (!tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           throw new Error("Tarefa não encontrada!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return tarefa;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // 5. Pesquisar tarefa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   function pesquisarTarefa() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const codigo = document.getElementById("buscarCodigo").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           alert(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       "Tarefa encontrada!\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   "Código: " + tarefa.codigo + "\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               "Título: " + tarefa.titulo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   alert(erro.message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // 6. Concluir tarefa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       function concluirTarefa(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (!tarefa.status) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       throw new Error("Essa tarefa já foi concluída!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       tarefa.status = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               listarTarefas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       alert("Tarefa concluída com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   alert(erro.message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // 7. Alterar prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       function alterarPrioridade(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const novaPrioridade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       prompt("Digite a nova prioridade:\n1 - Alta\n2 - Média\n3 - Baixa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (!Number.isInteger(novaPrioridade)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   throw new Error("Informe uma prioridade válida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   validarDadosDaTarefa(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               tarefa.titulo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           novaPrioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           tarefa.prioridade = novaPrioridade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   listarTarefas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           alert("Prioridade alterada com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       alert(erro.message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // 8. Evento de cadastro
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           document.getElementById("formTarefa").addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               "submit",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   function(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const titulo = document.getElementById("titulo").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const prioridade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       document.getElementById("prioridade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   cadastrarTarefa(titulo, prioridade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               alert("Tarefa cadastrada com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           document.getElementById("formTarefa").reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   } catch (erro) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               alert(erro.message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           );